import {combatCast,combatZones,combatName,combatOptions,combatThreats} from './combat.js';
const combatEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function combatButton(label,action,value='',disabled=false){return `<button data-action="${action}" data-value="${value}" ${disabled?'disabled':''}>${label}</button>`;}
function combatSilhouette(zombie=false){return `<svg viewBox="0 0 48 60" aria-hidden="true"><circle cx="24" cy="10" r="8"/><path d="${zombie?'M15 21 9 39 3 35 9 18 27 19 41 29 37 35 26 28 29 44 37 55 31 59 20 46 14 58 7 55 15 39Z':'M15 21h18l5 21-6 2-4-13v14l6 13h-8l-4-10-4 10h-8l6-16V31l-4 13-6-2Z'}"/></svg>`;}
export function combatSetupPage(state){return `<section class="battle-shell battle-setup"><header class="battle-top"><span class="battle-brand">CAMPUS / SURVIVAL</span>${combatButton('학교생활 메뉴','combatExit')}</header><article class="battle-intro"><span class="battle-kicker">전술 턴제 · 첫 전투 시제품</span><h1>방화문 너머로</h1><p class="battle-lead">예술동의 좁은 복도. 비틀거리는 사람들이 출구를 막았다.<br>목표는 상대를 전부 쓰러뜨리는 것이 아니라, <strong>둘 다 살아서 계단으로 나가는 것.</strong></p><div class="battle-rules"><p><b>01 · 보고 고르기</b>적의 위치와 동료 상태를 확인하고 각자 행동을 정하세요.</p><p><b>02 · 한 번에 실행</b>태이 → 동료 → 적 순서로 진행합니다. 고르는 동안 시간은 멈춰요.</p><p><b>03 · 문 열고 탈출</b>방화문은 두 번 당겨야 열려요. 10턴이 끝나기 전에 둘 다 탈출하세요.</p></div><label class="battle-select">함께할 인물<select id="combat-companion">${combatCast.map(id=>`<option value="${id}">${combatEscape(combatName(state,id))}</option>`).join('')}</select></label><p class="battle-preview-note">전투 구조를 시험하는 별도 장면입니다. 동료 선택은 학교생활의 실제 동행·통성명·관계를 바꾸지 않아요. 학교 시간·돈·소지품도 소모하지 않습니다.</p><div class="battle-start">${combatButton('복도에서 전투 시작','combatStart')}${state.combatTrial?combatButton(state.combatTrial.status==='active'?'진행 중인 전투 이어가기':'지난 전투 결과 보기','combatResume'):''}</div></article></section>`;}
function combatStats(state,key){const a=state.combatTrial.actors[key];return `<article class="battle-person ${a.down?'is-down':''}"><div class="battle-person-title"><i class="battle-face" data-face="${a.id}" aria-hidden="true"></i><span>${combatEscape(combatName(state,a.id))}</span><small>${a.escaped?'탈출 완료':a.down?'부축 필요':combatZones[a.zone]}</small></div><div class="battle-stamina"><span>스태미나 <b>${a.stamina}</b>/100</span><meter min="0" max="100" value="${a.stamina}" aria-label="${combatEscape(combatName(state,a.id))} 스태미나"></meter></div><div class="battle-needs"><span>공포 ${a.fear}${a.fear>=70?' · 매우 높음':''}</span><span>배고픔 ${a.hunger}</span><span>목마름 ${a.thirst}</span></div><p class="battle-wound">${a.wounds?`찰과상 ${a.wounds}회${a.down?' · 혼자 이동할 수 없음':''}`:'눈에 띄는 부상 없음'}</p></article>`;}
export function combatPlayPage(state,selected='taei',more=false,error=''){
 const b=state.combatTrial,planning=b.status==='active'&&b.phase==='planning',a=b.actors[selected],options=combatOptions(state,selected),threats=combatThreats(state);
 const zones=combatZones.map((name,index)=>`<article class="battle-zone ${index===3?'safe-zone':''}"><span class="battle-zone-number">0${index+1}</span><h3>${name}</h3><div class="battle-tokens">${Object.entries(b.actors).filter(([,p])=>p.zone===index).map(([key,p])=>`<div class="battle-token ${key==='taei'?'player-token':'ally-token'} ${p.down?'down-token':''}">${combatSilhouette()}<span>${key==='taei'?'태이':p.escaped?'동료 · 탈출':p.down?'동료 · 쓰러짐':'동료'}</span></div>`).join('')}${threats.filter(e=>e.zone===index).map(e=>`<div class="battle-token enemy-token ${b.enemies.find(x=>x.id===e.id).stun?'stunned-token':''}">${combatSilhouette(true)}<span>위협 ${e.id}${b.enemies.find(x=>x.id===e.id).stun?' · 견제':''}</span></div>`).join('')}</div>${index===2?`<span class="battle-door">방화문 ${b.door===2?'열림':b.door+'/2'}</span>`:index===3?'<span class="battle-door">두 사람이 모두 도착하면 성공</span>':''}</article>`).join('');
 return `<section class="battle-shell"><header class="battle-top"><span class="battle-brand">CAMPUS / SURVIVAL</span><div>${combatButton('저장 · 메뉴','openQuick')}${combatButton('학교생활 메뉴','combatExit')}</div></header><div class="battle-heading"><div><span class="battle-kicker">전투 시제품 · 학교생활과 별도</span><h1>방화문 너머로</h1><p>목표 <strong>둘 다 계단으로 탈출</strong> · 방화문 열기 ${b.door}/2</p></div><div class="battle-turn"><b>${b.turn}<small>/10 턴</small></b><span>${b.status==='escaped'?'탈출 성공':b.status==='failed'?'탈출 실패':planning?'행동 선택 중 · 시간 정지':'이번 턴 결과'}</span></div></div><div class="battle-pressure"><span>소음 <b>${b.noise}</b> · ${b.reinforced?'뒤쪽 위협 합류':b.noise>=4?'6에 도달하면 뒤쪽 위협 합류':'6에 도달하면 추가 위협'}</span><span>의자 ${b.items.chair} · 생수 ${b.items.water}${b.barrier?' · 장애물 유지 '+b.barrier+'턴':''}</span></div><div class="battle-map" aria-label="복도 전투 구역">${zones}</div><div class="battle-body"><aside class="battle-party">${combatStats(state,'taei')}${combatStats(state,'ally')}<details class="battle-threats"><summary>적의 다음 행동 ${threats.length}명</summary>${threats.map(t=>`<p>위협 ${t.id} · ${combatZones[t.zone]}<br>${t.label}</p>`).join('')||'<p>눈앞에 움직이는 적은 없어요. 출구로 이동하세요.</p>'}</details></aside><article class="battle-command">${error?`<p class="battle-error" role="alert">${combatEscape(error)}</p>`:''}${planning?`<div class="battle-actor-tabs" aria-label="행동할 인물 선택">${['taei','ally'].map(key=>`<button data-action="combatActor" data-value="${key}" aria-pressed="${selected===key}">${key==='taei'?'태이 행동':'동료 지시'}<small>${combatEscape(combatOptions(state,key).find(o=>o.id===b.plans[key])?.label??'행동 불가')}</small></button>`).join('')}</div><h2>${combatEscape(combatName(state,a.id))} · 무엇을 할까?</h2><p class="battle-command-guide">각자 하나를 고른 뒤 실행하세요.${b.actors.ally.fear>=70?' 동료의 공포가 높아 접근 공격을 거절할 수 있어요.':''}${b.carrying?' 부축 중이므로 동료는 태이와 함께 움직여요.':''}</p><div class="battle-action-grid">${options.filter(o=>more||['advance','shove','strike','brace'].includes(o.id)).map(o=>`<button data-action="combatPlan" data-value="${o.id}" ${o.disabled?'disabled':''} aria-pressed="${b.plans[selected]===o.id}"><strong>${o.label}</strong><span>${o.disabled?o.reason:o.detail}</span><small>${o.cost?'스태미나 −'+o.cost:'스태미나 회복'}${b.plans[selected]===o.id?' · 선택됨':''}</small></button>`).join('')}</div><div class="battle-command-footer">${combatButton(more?'기본 행동만 보기':'도구 · 후퇴 · 부축','combatTools')}<button class="battle-execute" data-action="combatExecute">두 사람의 행동 실행 →</button></div>`:`<h2>${b.status==='escaped'?'방화문이 닫혔다':b.status==='failed'?'탈출 기회를 놓쳤다':'이번 턴에 일어난 일'}</h2><ol class="battle-log" aria-live="polite">${b.log.map(line=>`<li>${combatEscape(line)}</li>`).join('')}</ol><div class="battle-command-footer">${b.status==='active'?combatButton('확인 · 다음 턴 행동 선택','combatNext'):combatButton('다른 행동으로 다시 해보기','combatSetup')}${combatButton('학교생활 메뉴','combatExit')}</div>`}</article></div><details class="battle-history"><summary>전투 기록 · ${b.history.length}턴</summary>${b.history.map(h=>`<section><h3>${h.turn}턴</h3>${h.log.map(line=>`<p>${combatEscape(line)}</p>`).join('')}</section>`).join('')||'<p>행동을 실행하면 여기에 결과가 남아요.</p>'}</details></section>`;
}
